head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[wframe > M > getParentFrame]<br/>중첩된 Frame 구조일때 가장 가까운 부모 Frame 객체를 반환합니다.",
    "validation" : [        
        "반환값으로 현재 WFrame 컴포넌트에서 가장 가까운 부모 Frame 객체를 반환합니다.",
        "일반적인 strictMode 환경에서 부모 Frame 객체가 없는 경우 메인 화면의 WFrame 객체를 반환합니다.",
        "strictMode 에서는 메인화면이 WFrame 으로 구성되므로 반환값은 항상 존재합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createBasicWframe();
}



scwin.btn_getParentFrame_onclick = function (e) {
    let rtn = ''

    rtn = target1.getParentFrame();
    wf_body_bottom.getObj("scwin").setReturnValue("getParentFrame().id : " + rtn.id);
};
